import React,{useState,useEffect,useCallback} from 'react';import {supabase} from '../lib/supabase';import {useAuth} from '../contexts/AuthContext';import {RotateCcw,Search,Undo2,Eye,Copy,X,Printer,Trash2,RefreshCw,AlertCircle} from 'lucide-react';import toast from 'react-hot-toast';
export default function ReturnHistory(){const {storeId,canDelete}=useAuth();const [returns,setReturns]=useState([]);const [loading,setLoading]=useState(true);const [error,setError]=useState(null);const [searchTerm,setSearchTerm]=useState('');const [companySettings,setCompanySettings]=useState({currency_symbol:'K',company_name:'Store'});const [selectedReturn,setSelectedReturn]=useState(null);const [showPreview,setShowPreview]=useState(false);
const loadReturns=useCallback(async()=>{if(!storeId)return;setLoading(true);setError(null);try{const {data,error}=await supabase.from('returns').select('*,sale:sales(*,customer:customers(name)),staff:staff(full_name)').eq('store_id',storeId).order('return_date',{ascending:false});if(error)throw error;setReturns(data||[]);}catch(err){setError(err.message);}finally{setLoading(false);}},[storeId]);
useEffect(()=>{if(storeId){loadReturns();supabase.from('company_settings').select('currency_symbol,company_name').eq('store_id',storeId).single().then(({data})=>{if(data)setCompanySettings(data);}).catch(()=>{});}},[storeId,loadReturns]);
const handleDeleteReturn=async(ret)=>{if(!canDelete)return toast.error('Only admin');if(!window.confirm('Delete permanently?'))return;try{await supabase.from('returns').delete().eq('id',ret.id);toast.success('Deleted');loadReturns();}catch(err){toast.error(err.message);}};
const handleUndoReturn=async(ret)=>{if(!canDelete)return toast.error('Only admin');if(!window.confirm('Undo this return?'))return;try{await supabase.from('sales').update({returned:false}).eq('id',ret.sale_id);await supabase.from('returns').delete().eq('id',ret.id);toast.success('Undone');loadReturns();}catch(err){toast.error(err.message);}};
const generateReceiptText=(ret)=>`${companySettings.company_name}\nRETURN RECEIPT\nInvoice #${ret.sale?.invoice_number}\nDate: ${new Date(ret.return_date).toLocaleString()}\nCustomer: ${ret.sale?.customer?.name||'Walk-in'}\nOriginal: ${companySettings.currency_symbol}${ret.sale?.total_amount?.toFixed(2)}\nRefund: ${companySettings.currency_symbol}${ret.refund_amount?.toFixed(2)}\nProcessed by: ${ret.staff?.full_name}`;
const handlePrint=(ret)=>{const w=window.open('','_blank');w.document.write(`<pre>${generateReceiptText(ret)}</pre><script>window.print()</script>`);w.document.close();};
const handleCopy=(ret)=>{navigator.clipboard?.writeText(generateReceiptText(ret));toast.success('Copied');};
const filtered=returns.filter(r=>r.sale?.invoice_number?.toString().includes(searchTerm)||r.sale?.customer?.name?.toLowerCase().includes(searchTerm.toLowerCase()));
return(<div className="p-4 h-full overflow-y-auto"><div className="flex items-center gap-2 mb-4"><h1 className="text-2xl font-bold"><RotateCcw className="inline mr-2"/>Return History</h1>{error&&<button onClick={loadReturns} className="ml-auto px-3 py-1 bg-blue-600 text-white rounded flex items-center gap-1"><RefreshCw size={14}/>Retry</button>}</div>{error&&<div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2"><AlertCircle className="text-red-600"/><span className="text-red-700">{error}</span></div>}<div className="mb-4 relative"><Search className="absolute left-3 top-2.5 text-gray-400" size={18}/><input placeholder="Search..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} className="w-full pl-10 p-2 border rounded-lg"/></div>{loading?<div className="text-center py-8">Loading...</div>:<div className="bg-white rounded-xl shadow overflow-hidden"><table className="w-full text-sm"><thead className="bg-gray-50 border-b"><tr><th className="p-3">Invoice #</th><th className="p-3">Return Date</th><th className="p-3">Customer</th><th className="p-3">Processed By</th><th className="p-3 text-right">Original</th><th className="p-3 text-right">Refund</th><th className="p-3 text-center">Actions</th></tr></thead><tbody>{filtered.length===0?<tr><td colSpan="7" className="p-8 text-center">No returns</td></tr>:filtered.map(r=>(<tr key={r.id} className="border-b hover:bg-gray-50"><td className="p-3">{r.sale?.invoice_number}</td><td className="p-3">{new Date(r.return_date).toLocaleString()}</td><td className="p-3">{r.sale?.customer?.name||'Walk-in'}</td><td className="p-3">{r.staff?.full_name}</td><td className="p-3 text-right">{companySettings.currency_symbol}{r.sale?.total_amount?.toFixed(2)}</td><td className="p-3 text-right text-green-600">{companySettings.currency_symbol}{r.refund_amount?.toFixed(2)}</td><td className="p-3"><div className="flex gap-1 justify-center"><button onClick={()=>{setSelectedReturn(r);setShowPreview(true);}} className="p-1.5 text-purple-600 hover:bg-purple-50 rounded"><Eye size={18}/></button><button onClick={()=>handlePrint(r)} className="p-1.5 text-gray-600 hover:bg-gray-100 rounded"><Printer size={18}/></button><button onClick={()=>handleCopy(r)} className="p-1.5 text-green-600 hover:bg-green-50 rounded"><Copy size={18}/></button>{canDelete&&<><button onClick={()=>handleUndoReturn(r)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded"><Undo2 size={18}/></button><button onClick={()=>handleDeleteReturn(r)} className="p-1.5 text-red-600 hover:bg-red-50 rounded"><Trash2 size={18}/></button></>}</div></td></tr>))}</tbody></table></div>}{showPreview&&selectedReturn&&(<div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"><div className="bg-white rounded-xl w-full max-w-md"><div className="p-4 border-b flex justify-between"><h2 className="font-bold">Return Receipt</h2><button onClick={()=>setShowPreview(false)}><X/></button></div><div className="p-4 font-mono text-sm whitespace-pre-wrap">{generateReceiptText(selectedReturn)}</div><div className="p-4 border-t flex justify-end gap-2"><button onClick={()=>handlePrint(selectedReturn)} className="px-3 py-1.5 bg-blue-600 text-white rounded">Print</button><button onClick={()=>handleCopy(selectedReturn)} className="px-3 py-1.5 bg-gray-600 text-white rounded">Copy</button><button onClick={()=>setShowPreview(false)} className="px-3 py-1.5 bg-gray-200 rounded">Close</button></div></div></div>)}</div>);}
